sp_widget.client_script:
api.controller = function() {

    var c = this;

    // Search Risk Assessments
    c.search = function() {
        c.server.update();
    };


    // Clear Search
    c.clearSearch = function() {
        c.searchText = '';
        c.server.update();
    };


    // Add New Risk
    c.addRisk = function() {

        window.location.href =
        'sc_cat_item.do?sys_id=<RISK_RECORD_PRODUCER_SYS_ID>';

    };

};

sp_widget.css:
.risk-page {
  background: #f5f9f8;
  padding: 28px;
  border-radius: 12px;
  font-family: Arial, sans-serif;
}

/* Header */
.risk-header {
  background: linear-gradient(135deg, #006b63, #008f83);
  color: #ffffff;
  padding: 28px 30px;
  border-radius: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.brand-title {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 1px;
}

.brand-icon {
  margin-right: 8px;
}

.brand-subtitle {
  font-size: 11px;
  color: #b8f28c;
  margin-top: 5px;
  letter-spacing: 1px;
}

.risk-header h1 {
  margin: 18px 0 5px;
  font-size: 28px;
}

.risk-header p {
  margin: 0;
  font-size: 14px;
  opacity: 0.9;
}

/* New Risk */
.new-risk-btn {
  background: #b8f28c;
  color: #075b50;
  border: none;
  padding: 12px 20px;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}

.new-risk-btn:hover {
  opacity: 0.9;
}

/* Toolbar */
.risk-toolbar {
  background: #ffffff;
  padding: 16px;
  border-radius: 12px;
  margin-bottom: 18px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.search-box input {
  flex: 1;
  height: 42px;
  border: 1px solid #d7e5e2;
  border-radius: 8px;
  padding: 0 14px;
  outline: none;
}

.search-box input:focus {
  border-color: #008f83;
}

.search-box button {
  height: 42px;
  padding: 0 20px;
  background: #008f83;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

/* Table Card */
.risk-card {
  background: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 12px rgba(0,0,0,0.07);
}

/* Table */
.risk-table {
  width: 100%;
  border-collapse: collapse;
}

.risk-table th {
  background: #eaf5f2;
  color: #075b50;
  text-align: left;
  padding: 15px 14px;
  font-size: 12px;
  font-weight: 700;
}

.risk-table td {
  padding: 15px 14px;
  border-bottom: 1px solid #edf2f1;
  font-size: 13px;
  color: #344746;
}

.risk-row:hover {
  background: #f7fbfa;
}

/* Risk ID */
.risk-id {
  color: #007f73;
  font-weight: 700;
  text-decoration: none;
}

.risk-id:hover {
  text-decoration: underline;
}

/* Risk badges */
.risk-badge,
.status-badge {
  display: inline-block;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

/* Risk levels */
.risk-high {
  background: #fde2e2;
  color: #b42318;
}

.risk-medium {
  background: #fff0d6;
  color: #a15c00;
}

.risk-low {
  background: #dcf5e8;
  color: #167447;
}

/* Status */
.status-in-progress {
  background: #e2efff;
  color: #1769aa;
}

.status-completed {
  background: #dcf5e8;
  color: #167447;
}

.status-pending {
  background: #fff0d6;
  color: #a15c00;
}

.status-assigned {
  background: #e8f0ff;
  color: #4264a8;
}

/* Empty */
.empty-state {
  text-align: center !important;
  padding: 45px !important;
  color: #879998 !important;
}

/* Responsive */
@media (max-width: 768px) {

  .risk-page {
    padding: 15px;
  }

  .risk-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }

  .new-risk-btn {
    width: 100%;
  }

  .search-box {
    flex-direction: column;
    align-items: stretch;
  }

  .search-box button {
    width: 100%;
  }

  .risk-card {
    overflow-x: auto;
  }

  .risk-table {
    min-width: 800px;
  }
}

sp_widget.script:
(function() {

    /* ==========================================
       EXISTING ENVIRONMENTAL RISK TABLE
       ========================================== */

    var TABLE = 'x_snc_environmen_0_environmental_risk';

    var gr = new GlideRecord(TABLE);

    data.risks = [];


    /* ==========================================
       SEARCH
       ========================================== */

    if (input && input.searchText) {

        var text = input.searchText.trim();

        if (text) {

            var query = null;

            if (gr.isValidField('number')) {
                query = gr.addQuery('number', 'CONTAINS', text);
            }

            if (gr.isValidField('risk_type')) {

                if (query) {
                    query.addOrCondition('risk_type', 'CONTAINS', text);
                } else {
                    query = gr.addQuery(
                        'risk_type',
                        'CONTAINS',
                        text
                    );
                }
            }

            if (gr.isValidField('location')) {

                if (query) {
                    query.addOrCondition(
                        'location',
                        'CONTAINS',
                        text
                    );
                } else {
                    query = gr.addQuery(
                        'location',
                        'CONTAINS',
                        text
                    );
                }
            }

            if (gr.isValidField('risk_level')) {

                if (query) {
                    query.addOrCondition(
                        'risk_level',
                        'CONTAINS',
                        text
                    );
                } else {
                    query = gr.addQuery(
                        'risk_level',
                        'CONTAINS',
                        text
                    );
                }
            }

            if (gr.isValidField('status')) {

                if (query) {
                    query.addOrCondition(
                        'status',
                        'CONTAINS',
                        text
                    );
                } else {
                    query = gr.addQuery(
                        'status',
                        'CONTAINS',
                        text
                    );
                }
            }
        }
    }


    /* ==========================================
       QUERY RECORDS
       ========================================== */

    if (gr.isValidField('sys_created_on')) {
        gr.orderByDesc('sys_created_on');
    }

    gr.setLimit(50);
    gr.query();


    /* ==========================================
       BUILD RISK DATA
       ========================================== */

    while (gr.next()) {

        var risk = {};


        /* Risk ID */

        if (gr.isValidField('number')) {
            risk.number = gr.getDisplayValue('number');
        } else if (gr.isValidField('risk_id')) {
            risk.number = gr.getDisplayValue('risk_id');
        } else {
            risk.number = gr.getUniqueValue();
        }


        /* Risk Type */

        if (gr.isValidField('risk_type')) {
            risk.type = gr.getDisplayValue('risk_type');
        } else if (gr.isValidField('type')) {
            risk.type = gr.getDisplayValue('type');
        } else {
            risk.type = 'Environmental Risk';
        }


        /* Location */

        if (gr.isValidField('location')) {
            risk.location = gr.getDisplayValue('location');
        } else if (gr.isValidField('region')) {
            risk.location = gr.getDisplayValue('region');
        } else {
            risk.location = 'Not specified';
        }


        /* Risk Level */

        if (gr.isValidField('risk_level')) {
            risk.level = gr.getDisplayValue('risk_level');
        } else if (gr.isValidField('risk')) {
            risk.level = gr.getDisplayValue('risk');
        } else {
            risk.level = 'Not specified';
        }


        /* Status */

        if (gr.isValidField('status')) {
            risk.status = gr.getDisplayValue('status');
        } else {
            risk.status = 'Active';
        }


        /* Assessment Date */

        if (gr.isValidField('assessment_date')) {
            risk.assessmentDate =
                gr.getDisplayValue('assessment_date');

        } else if (gr.isValidField('risk_assessment_date')) {
            risk.assessmentDate =
                gr.getDisplayValue('risk_assessment_date');

        } else {
            risk.assessmentDate =
                gr.getDisplayValue('sys_created_on');
        }


        /* Push record */

        data.risks.push(risk);
    }


})();
